-- PULSE Batch 5: Academy, Global, Meet
CREATE TABLE IF NOT EXISTS public.academy_courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE, slug text NOT NULL, title text NOT NULL, summary text, description text, level text NOT NULL DEFAULT 'beginner' CHECK(level IN ('beginner','intermediate','advanced')), domain text, estimated_minutes integer CHECK(estimated_minutes IS NULL OR estimated_minutes > 0), cover_image_path text, published boolean NOT NULL DEFAULT false, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TABLE IF NOT EXISTS public.academy_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE,position integer NOT NULL CHECK(position>0),title text NOT NULL,UNIQUE(course_id,position));
CREATE TABLE IF NOT EXISTS public.academy_lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),module_id uuid NOT NULL REFERENCES public.academy_modules(id) ON DELETE CASCADE,position integer NOT NULL CHECK(position>0),title text NOT NULL,content_type text NOT NULL CHECK(content_type IN ('markdown','video','interactive')),content_path text,content_body text,estimated_minutes integer NOT NULL DEFAULT 5 CHECK(estimated_minutes>0),UNIQUE(module_id,position));
CREATE TABLE IF NOT EXISTS public.academy_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,enrolled_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,progress_percent numeric(5,2) NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100),UNIQUE(course_id,user_id));
CREATE TABLE IF NOT EXISTS public.academy_lesson_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enrollment_id uuid NOT NULL REFERENCES public.academy_enrollments(id) ON DELETE CASCADE,lesson_id uuid NOT NULL REFERENCES public.academy_lessons(id) ON DELETE CASCADE,completed_at timestamptz NOT NULL DEFAULT now(),time_spent_seconds integer NOT NULL DEFAULT 0 CHECK(time_spent_seconds>=0),UNIQUE(enrollment_id,lesson_id));
CREATE TABLE IF NOT EXISTS public.academy_quizzes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE,module_id uuid REFERENCES public.academy_modules(id) ON DELETE SET NULL,title text NOT NULL,pass_score numeric(5,2) NOT NULL DEFAULT 80 CHECK(pass_score BETWEEN 0 AND 100),questions jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(jsonb_typeof(questions)='array'));
CREATE TABLE IF NOT EXISTS public.academy_quiz_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid NOT NULL REFERENCES public.academy_quizzes(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,score numeric(5,2) NOT NULL CHECK(score BETWEEN 0 AND 100),passed boolean NOT NULL,answers jsonb,attempt_number integer NOT NULL CHECK(attempt_number>0),attempted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(quiz_id,user_id,attempt_number));
CREATE TABLE IF NOT EXISTS public.academy_certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,certificate_number text UNIQUE NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,pdf_path text,vc_id uuid,revoked boolean NOT NULL DEFAULT false,signature text NOT NULL,public_key text NOT NULL,verification_payload text NOT NULL,UNIQUE(course_id,user_id));
CREATE TABLE IF NOT EXISTS public.i18n_locales (code text PRIMARY KEY,name text NOT NULL,native_name text,direction text NOT NULL DEFAULT 'ltr' CHECK(direction IN ('ltr','rtl')),enabled boolean NOT NULL DEFAULT true,fallback text REFERENCES public.i18n_locales(code));
CREATE TABLE IF NOT EXISTS public.i18n_translations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),locale text NOT NULL REFERENCES public.i18n_locales(code) ON DELETE CASCADE,namespace text NOT NULL,key text NOT NULL,value text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES auth.users(id),UNIQUE(locale,namespace,key));
CREATE TABLE IF NOT EXISTS public.i18n_user_prefs (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,locale text REFERENCES public.i18n_locales(code),timezone text,number_format text NOT NULL DEFAULT 'auto',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.a11y_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE,page_path text NOT NULL,wcag_level text NOT NULL DEFAULT 'AA',score numeric(5,2),violations jsonb NOT NULL DEFAULT '[]'::jsonb,audited_at timestamptz NOT NULL DEFAULT now(),audit_run_id uuid NOT NULL DEFAULT gen_random_uuid());
CREATE TABLE IF NOT EXISTS public.meet_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE,name text NOT NULL,host_id uuid REFERENCES auth.users(id),max_participants integer NOT NULL DEFAULT 20 CHECK(max_participants BETWEEN 2 AND 100),recording_enabled boolean NOT NULL DEFAULT false,transcript_enabled boolean NOT NULL DEFAULT false,requires_approval boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','live','ended')),scheduled_at timestamptz,started_at timestamptz,ended_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.meet_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_id uuid NOT NULL REFERENCES public.meet_rooms(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,display_name text,role text NOT NULL DEFAULT 'attendee' CHECK(role IN ('host','cohost','attendee','observer')),status text NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','joined','left','denied')),joined_at timestamptz,left_at timestamptz,UNIQUE(room_id,user_id));
CREATE TABLE IF NOT EXISTS public.meet_recordings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_id uuid NOT NULL REFERENCES public.meet_rooms(id) ON DELETE CASCADE,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,duration_seconds integer,size_bytes bigint,storage_path text,status text NOT NULL DEFAULT 'recording' CHECK(status IN ('recording','processing','completed','failed')));
CREATE TABLE IF NOT EXISTS public.meet_transcripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recording_id uuid NOT NULL REFERENCES public.meet_recordings(id) ON DELETE CASCADE,language text NOT NULL DEFAULT 'en',transcript_json jsonb,storage_path text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.meet_signals (id bigserial PRIMARY KEY,room_id uuid NOT NULL REFERENCES public.meet_rooms(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES auth.users(id),recipient_id uuid NOT NULL REFERENCES auth.users(id),signal_type text NOT NULL CHECK(signal_type IN ('offer','answer','ice','join','leave')),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_academy_courses_org_pub ON public.academy_courses(organization_id,published); CREATE INDEX IF NOT EXISTS idx_academy_enroll_user ON public.academy_enrollments(user_id,enrolled_at DESC); CREATE INDEX IF NOT EXISTS idx_academy_attempts_user ON public.academy_quiz_attempts(user_id,attempted_at DESC); CREATE INDEX IF NOT EXISTS idx_i18n_lookup ON public.i18n_translations(locale,namespace); CREATE INDEX IF NOT EXISTS idx_meet_participants_room ON public.meet_participants(room_id,status); CREATE INDEX IF NOT EXISTS idx_meet_signals_recipient ON public.meet_signals(recipient_id,created_at); CREATE INDEX IF NOT EXISTS idx_meet_rooms_org_status ON public.meet_rooms(organization_id,status);
INSERT INTO public.i18n_locales(code,name,native_name,direction,fallback) VALUES ('en','English','English','ltr','en'),('fr','French','Français','ltr','en'),('ar','Arabic','العربية','rtl','en'),('sw','Swahili','Kiswahili','ltr','en'),('zh','Chinese (Simplified)','简体中文','ltr','en'),('es','Spanish','Español','ltr','en') ON CONFLICT(code) DO NOTHING;
ALTER TABLE public.academy_courses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_modules ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_lessons ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_enrollments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_lesson_progress ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_quizzes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_quiz_attempts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.academy_certificates ENABLE ROW LEVEL SECURITY; ALTER TABLE public.i18n_locales ENABLE ROW LEVEL SECURITY; ALTER TABLE public.i18n_translations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.i18n_user_prefs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.a11y_audits ENABLE ROW LEVEL SECURITY; ALTER TABLE public.meet_rooms ENABLE ROW LEVEL SECURITY; ALTER TABLE public.meet_participants ENABLE ROW LEVEL SECURITY; ALTER TABLE public.meet_recordings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.meet_transcripts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.meet_signals ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.pulse_is_org_member(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=p_org AND m.user_id=auth.uid()) $$;
CREATE POLICY academy_courses_member ON public.academy_courses FOR SELECT USING (organization_id IS NOT NULL AND public.pulse_is_org_member(organization_id) AND published=true); CREATE POLICY academy_enroll_self ON public.academy_enrollments FOR SELECT USING (user_id=auth.uid()); CREATE POLICY academy_progress_self ON public.academy_lesson_progress FOR SELECT USING (EXISTS(SELECT 1 FROM public.academy_enrollments e WHERE e.id=enrollment_id AND e.user_id=auth.uid())); CREATE POLICY academy_attempt_self ON public.academy_quiz_attempts FOR SELECT USING (user_id=auth.uid()); CREATE POLICY academy_cert_self ON public.academy_certificates FOR SELECT USING (user_id=auth.uid());
CREATE POLICY i18n_locale_read ON public.i18n_locales FOR SELECT USING (enabled=true); CREATE POLICY i18n_translation_read ON public.i18n_translations FOR SELECT USING (EXISTS(SELECT 1 FROM public.i18n_locales l WHERE l.code=locale AND l.enabled=true)); CREATE POLICY i18n_pref_self ON public.i18n_user_prefs USING (user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE POLICY a11y_org_read ON public.a11y_audits FOR SELECT USING (organization_id IS NOT NULL AND public.pulse_is_org_member(organization_id));
CREATE POLICY meet_room_member ON public.meet_rooms FOR SELECT USING (organization_id IS NOT NULL AND public.pulse_is_org_member(organization_id)); CREATE POLICY meet_participant_self ON public.meet_participants FOR SELECT USING (user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.meet_rooms r WHERE r.id=room_id AND r.host_id=auth.uid())); CREATE POLICY meet_recording_member ON public.meet_recordings FOR SELECT USING (EXISTS(SELECT 1 FROM public.meet_rooms r WHERE r.id=room_id AND public.pulse_is_org_member(r.organization_id))); CREATE POLICY meet_transcript_member ON public.meet_transcripts FOR SELECT USING (EXISTS(SELECT 1 FROM public.meet_recordings x JOIN public.meet_rooms r ON r.id=x.room_id WHERE x.id=recording_id AND public.pulse_is_org_member(r.organization_id))); CREATE POLICY meet_signal_participant ON public.meet_signals FOR SELECT USING (sender_id=auth.uid() OR recipient_id=auth.uid());
ALTER PUBLICATION supabase_realtime ADD TABLE public.academy_enrollments; ALTER PUBLICATION supabase_realtime ADD TABLE public.academy_lesson_progress; ALTER PUBLICATION supabase_realtime ADD TABLE public.academy_certificates; ALTER PUBLICATION supabase_realtime ADD TABLE public.meet_signals; ALTER PUBLICATION supabase_realtime ADD TABLE public.meet_participants;
